import{courseCoordinates}from'./traversal-layout.js';
const FIRST={rocks:'Watch the first stones. Jump toward a clear landing; cracked stones will crumble.',plants:'Watch a plant change from amber to purple. Wait for the burst to clear.',steps:'Try the steps at your own pace. Jump is available when you need it.',coins:'Follow the coins and try turning. Your next English discovery is ahead.',boulders:'Watch one boulder pass first. Amber marks its route; alcoves are resting places.',wind:'Watch the flags. Wait behind a shelter until the gust passes.',moving:'Watch a platform complete a trip. Board it when it comes close.',thorns:'Look for the green opening. Amber previews where it moves next.',crystals:'Watch the crystal shells open. Then strike an exposed core.',bonus:'The leaf route is safe. Try the raised gold route for extra coins.'};
export function approachGuidance(nav){const s=nav?.section;if(!s||nav.combat?.blocking?.active)return'';const q=courseCoordinates(s,nav.player);if(q.s<0||q.s>3.8)return'';return FIRST[s.trial?.kind||s.kind]||'';}
export function practiceGoal(level){return level>=6?'Listen for three requested items and follow their order.':level>=5?'Build English sentences with fewer translation clues.':level>=3?'Expect longer sentences and more detailed meanings.':'Connect meanings and learn how each mechanism works.';}
